package com.example.app.model;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Mutable entity.
 *
 * @Data generates getters, setters, equals, hashCode and toString.
 * Constructors are generated explicitly below.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class User {

    private Long id;
    private String username;
    private String email;
    private boolean active;
}

package com.example.app.model;

import java.math.BigDecimal;

import lombok.Builder;
import lombok.Value;
import lombok.With;

/**
 * Immutable DTO.
 *
 * @Value makes all fields private final, generates getters, equals, hashCode,
 * toString and an all-args constructor (no setters).
 * @With generates "wither" copy methods for safe updates.
 */
@Value
@Builder
@With
public class Product {

    String sku;
    String name;
    BigDecimal price;
    int quantity;
}

package com.example.app;

import java.math.BigDecimal;

import com.example.app.model.Product;
import com.example.app.model.User;

import lombok.extern.slf4j.Slf4j;

/**
 * Small entry point showing the Lombok-generated API in action.
 * @Slf4j injects a private static final org.slf4j.Logger "log".
 */
@Slf4j
public class Application {

    public static void main(String[] args) {
        User user = User.builder()
                .id(1L)
                .username("ada")
                .email("ada@example.com")
                .active(true)
                .build();
        // setter generated by @Data
        user.setEmail("ada.lovelace@example.com");
        log.info("user={}", user);

        Product product = Product.builder()
                .sku("SKU-1")
                .name("Keyboard")
                .price(new BigDecimal("49.99"))
                .quantity(3)
                .build();
        // wither generated by @With (returns a copy)
        Product discounted = product.withPrice(new BigDecimal("39.99"));
        log.info("product={}", product);
        log.info("discounted={}", discounted);
    }
}

package com.example.app.model;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.math.BigDecimal;

import org.junit.jupiter.api.Test;

class ModelTest {

    @Test
    void dataGeneratesAccessorsAndValueSemantics() {
        User user = User.builder().id(1L).username("ada").email("ada@example.com").active(true).build();

        user.setEmail("ada.lovelace@example.com");
        assertEquals("ada.lovelace@example.com", user.getEmail());

        User same = new User(1L, "ada", "ada.lovelace@example.com", true);
        assertEquals(user, same);
        assertEquals(user.hashCode(), same.hashCode());

        User different = User.builder().id(2L).username("grace").build();
        assertNotEquals(user, different);
    }

    @Test
    void valueIsImmutableAndWithReturnsCopies() {
        Product product = Product.builder()
                .sku("SKU-1")
                .name("Keyboard")
                .price(new BigDecimal("49.99"))
                .quantity(3)
                .build();

        Product discounted = product.withPrice(new BigDecimal("39.99"));

        assertNotSame(product, discounted);
        assertEquals(new BigDecimal("49.99"), product.getPrice());
        assertEquals(new BigDecimal("39.99"), discounted.getPrice());
        assertEquals(product.getSku(), discounted.getSku());
        assertTrue(product.toString().contains("Keyboard"));
    }
}
